#!/usr/bin/env python3
"""Build a self-contained, offline pose comparison page for the local MMA clips."""

from __future__ import annotations

import html
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
SAMPLES_PATH = ROOT / "work" / "samples.json"
POSE_DIR = ROOT / "outputs" / "pose"
OUT = ROOT / "outputs" / "review.html"


def load_json(path: Path):
    with path.open(encoding="utf-8") as f:
        return json.load(f)


def build() -> None:
    samples = load_json(SAMPLES_PATH)
    bundle = []
    for sample in samples:
        sid = sample["id"]
        models = {}
        for key in ("generic", "mma", "rtmw"):
            pose_path = POSE_DIR / f"{sid}__{key}.json"
            if pose_path.exists():
                models[key] = load_json(pose_path)
        phase_path = ROOT / "outputs" / "phases" / f"{sid}.json"
        blood_path = ROOT / "outputs" / "blood" / f"{sid}.json"
        bundle.append({
            **sample,
            "models": models,
            "phase": load_json(phase_path) if phase_path.exists() else None,
            "blood": load_json(blood_path) if blood_path.exists() else None,
            "clip": f"clips/{sid}.mp4",
        })

    payload = json.dumps(bundle, ensure_ascii=False, separators=(",", ":"))
    # Escape HTML-sensitive characters because JSON is placed inside a script element.
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(PAGE.replace("__DATA__", payload), encoding="utf-8")
    print(f"Wrote {OUT} ({OUT.stat().st_size:,} bytes, {len(bundle)} samples)")


